import {getPlan,slidingDoorConflicts} from './specification.js';
import {OPTIONAL_ITEMS,OPTION_GROUPS,itemById,selectedOption,availableOptionTargets,optionTargetLabel,catalogueEstimate,money,CATALOGUE_EDITION} from './project-options.js';
import {DATA} from './data.js';
import {STANDARD_PACKAGE,ADAPTATION_REQUESTS,adaptationEstimate,standardDescription} from './standard-package.js';
import {INTERIOR_REFERENCES} from './interior-references.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(key,label,value,multiline=false)=>`<label class="project-field"><span>${label}</span>${multiline?`<textarea data-project-field="${key}" rows="3" maxlength="2400">${esc(value)}</textarea>`:`<input data-project-field="${key}" type="${key==='projectDate'?'date':'text'}" maxlength="160" value="${esc(value)}" ${key==='clientName'?'autocomplete="name"':''}>`}</label>`;
export function standardSpecificationMarkup(kind,state){
 const kitchen=kind==='kitchen',standard=STANDARD_PACKAGE[kind],ref=INTERIOR_REFERENCES[standard.ref];
 const changes=adaptationEstimate(state).lines.filter(item=>item.kind===kind),extra=selectedOption(state,kitchen?'kitchen-upper':'bathroom-separated');
 const atStandard=!changes.length&&!extra,blocked=kitchen&&state.layout==='t4-a';
 return `<section class="standard-spec"><span class="eyebrow">INCLUÍDO NO MODELO STANDARD</span><h3>${standard.title}</h3><button class="standard-photo" data-lightbox="${ref.sourceAsset}" data-label="${standard.title}" aria-label="Ampliar fotografia do standard"><img src="${ref.sourceAsset}" alt="${standard.title} · fotografia confirmada pela Green Village"><span>Referência ${standard.ref.slice(-2)} · fotografia original ↗</span></button><p>${standard.description}</p><p class="field-description">${standard.limit}</p><p class="standard-status">${atStandard?'✓ Standard seleccionado':'Configuração personalizada · acréscimos separados'}</p>${blocked?'<p class="project-attention">Nesta planta T4 A, a cozinha em L não cabe na zona prevista. A implantação linear é uma adaptação sujeita a orçamento.</p>':`<button class="outline" data-use-standard="${kind}">${atStandard?'Standard aplicado':'Repor '+(kitchen?'cozinha':'banho')+' standard'}</button>`}<dl><div><dt>${kitchen?'Armário superior opcional':'Alterações ao banho original'}</dt><dd>${kitchen?money(itemById('kitchen-upper').priceCents)+' com IVA · PVP de '+CATALOGUE_EDITION+'. Conjunto de módulos abrangido por confirmar.':'Bancada, posição do lavatório e ampliação têm acréscimos próprios, a definir na proposta.'}</dd></div></dl><button class="text-link" data-customize="options">Fotografias e adicionais ↗</button></section>`;
}

export function adaptationControlsMarkup(kind,state){
 const lines=adaptationEstimate(state).lines.filter(line=>line.kind===kind);
 const mirrored=kind==='bathroom'&&state.bathroom==='mirrored';
 const controls=ADAPTATION_REQUESTS.filter(item=>item.kind===kind).map(item=>{
  const derived=mirrored&&item.id==='bathroom-basin-position',checked=derived||(state.adaptationRequests||[]).includes(item.id);
  return `<label><input id="adaptation-${item.id}" type="checkbox" data-adaptation="${item.id}" ${checked?'checked':''} ${derived?'disabled aria-describedby="mirrored-basin-note"':''}><span>${item.label}<small>Sob orçamento${derived?' · associado à distribuição espelhada':''}</small></span></label>`;
 }).join('');
 return `<section class="adaptation-controls"><h3>Personalizações do ${kind==='kitchen'?'espaço da cozinha':'banho'}</h3><p>Cada alteração tem um acréscimo próprio. Seleccione o que pretende orçamentar.</p><div class="option-targets">${controls}</div>${mirrored?'<p id="mirrored-basin-note" class="field-description">A distribuição espelhada altera a posição do lavatório. Para retirar esta alteração, escolha Distribuição base abaixo e desmarque o pedido, se o tiver seleccionado manualmente.</p>':''}${lines.length?`<div class="adaptation-pending" role="status"><strong>${lines.length} ${lines.length===1?'alteração por orçamentar':'alterações por orçamentar'}</strong><ul>${lines.map(line=>`<li>${esc(line.label)} — Sob orçamento</li>`).join('')}</ul></div>`:''}<p class="field-description">Os pedidos acima ficam na ficha. Medidas, posição exacta e material serão definidos com a Green Village; o 3D mantém a implantação escolhida abaixo.</p><button class="text-link" data-customize="project">Acrescentar medidas e observações ↗</button></section>`;
}
export function optionsPanelMarkup(state,plan,filter='all'){
 const estimate=catalogueEstimate(state);
 return `<div class="options-intro"><span class="eyebrow">PVP ACTUALIZADO · ${CATALOGUE_EDITION}</span><h3>Adicionais à sua medida.</h3><p>Escolha os artigos e os locais onde pretende aplicá-los. As selecções acompanham a planta, o resumo e o PDF.</p><label class="project-field"><span>Categoria de adicionais</span><select id="option-category"><option value="all">Todos os 22 artigos</option><option value="selected" ${filter==='selected'?'selected':''}>Os meus adicionais (${estimate.lines.length})</option>${Object.entries(OPTION_GROUPS).map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="option-subtotal"><span>Subtotal indicativo dos adicionais</span><strong>${money(estimate.knownSubtotalCents)}</strong><small>IVA incluído · base da casa por confirmar${estimate.pending.length?' · há artigos sob consulta':''}</small></div></div><div class="option-cards">${OPTIONAL_ITEMS.filter(item=>filter==='all'||(filter==='selected'?Boolean(selectedOption(state,item.id)):item.section===filter)).map(item=>{
 const selected=selectedOption(state,item.id),targets=availableOptionTargets(item,plan),variant=selected?.variant||item.variants[0]?.[0];
 const conflicts=item.id==='interior-door'&&variant==='sliding'?slidingDoorConflicts(getPlan({...state,optionSelections:[{id:item.id,quantity:plan.doors.length,targets:plan.doors.map(d=>d.id),variant}]})):[];
 return `<article class="option-card ${selected?'is-selected':''}" data-option-card="${item.id}"><div class="option-photo">${item.photo?`<button data-lightbox="${item.photo}" data-label="${esc(item.label)}" aria-label="Ampliar fotografia de ${esc(item.label)}"><img src="${item.photo}" loading="lazy" alt="${esc(item.label)} — imagem do catálogo"></button><small class="option-photo-caption">${esc(item.photoCaption)}</small>`:`<a href="assets/opcionais-2026.pdf#page=${item.page}" target="_blank" rel="noopener"><span>Consultar artigo no catálogo ↗</span><small>Sem fotografia individual identificada</small></a>`}</div><div class="option-card-body"><span class="option-category">${OPTION_GROUPS[item.section]} · p. ${item.page}</span><h4>${esc(item.label)}</h4><p class="option-price">${money(item.priceCents)} <small>${item.priceCents==null?'Valor por confirmar':'com IVA'}</small></p><ul>${item.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="option-scope">${esc(item.scope)}</p><button class="${selected?'outline':'primary'} option-select" data-toggle-option="${item.id}" aria-pressed="${Boolean(selected)}">${selected?'✓ Seleccionado · retirar':'Adicionar ao projecto'}</button>${selected?`<div class="option-settings">${item.maxQuantity>1?`<label class="project-field"><span>Quantidade pretendida</span><input type="number" min="1" max="${item.maxQuantity}" step="1" value="${selected.quantity}" data-option-quantity="${item.id}"></label>`:''}${item.variants.length?`<label class="project-field"><span>Tipo de porta</span><select data-option-variant="${item.id}">${item.variants.map(([id,label])=>`<option value="${id}" ${variant===id?'selected':''}>${label}</option>`).join('')}</select></label>`:''}${targets.length&&item.id!=='glass-front'?`<details open><summary>Aplicar nos vãos da planta</summary><p class="field-description">Escolha o local para ver a proposta em 3D. Seleccionar outro tipo substitui a escolha desse vão.</p><div class="option-targets">${targets.map(t=>`<label><input id="option-target-${item.id}-${t.id}" type="checkbox" data-option-target="${item.id}" value="${t.id}" ${selected.targets.includes(t.id)?'checked':''} ${conflicts.some(c=>c.targetId===t.id)?'disabled':''}>${esc(t.label)}${conflicts.some(c=>c.targetId===t.id)?' · sem espaço de recolha nesta planta':''}</label>`).join('')}</div><small>${selected.targets.length} de ${selected.quantity} locais definidos</small></details>`:''}${item.id==='window-mosquito'?`<p class="option-model-note">Este artigo destina-se a janelas. Ao substituir uma janela por uma porta, o mosquiteiro mantém-se na ficha, com a mesma quantidade e preço, mas fica por atribuir.</p>${selected.targets.length<selected.quantity?`<p class="project-attention">${selected.quantity-selected.targets.length} ${selected.quantity-selected.targets.length===1?'mosquiteiro por atribuir':'mosquiteiros por atribuir'}. Escolha uma janela ou ajuste a quantidade pretendida.</p>`:''}`:''}${item.id==='exterior-3d'?'<button class="outline" data-option-finish>Escolher a textura do painel ↗</button>':''}${['window-large','window-alloy','window-thermal','window-projecting','window-tilt-turn'].includes(item.id)?'<p class="option-model-note">Pré-visualização com caixilho fechado representativo. O mecanismo de abertura desta referência ainda não está modelado.</p>':''}${item.model==='specification'?`<p class="option-model-note">Registado na especificação e no PDF.${item.section==='walls'?' A geometria das camadas da casa é representativa; esta escolha não valida espessuras totais ou ligações.':''}</p>`:`<button class="text-link" data-preview-option="${item.id}">Ver no modelo ↗</button>`}${!['rockwool','eps','gable-roof','terrace'].includes(item.id)?'<p class="option-model-note">Cálculo indicativo: quantidade × PVP actual. Unidade de facturação e inclusão na casa a confirmar na proposta.</p>':''}${item.section==='doors'||item.section==='windows'?'<p class="option-model-note">Dimensões não publicadas mantêm as medidas ilustrativas do vão. A instalação e as alterações da planta carecem de confirmação.</p>':''}<a class="text-link" href="assets/opcionais-2026.pdf#page=${item.page}" target="_blank" rel="noopener">Ficha original · preços anteriores ↗</a></div>`:''}</div></article>`;
 }).join('')}</div><button class="primary options-review" data-summary>Rever artigos e custos ↗</button>`;
}
export function clientProjectMarkup(project,state){
 return `<div class="project-intro"><span class="eyebrow">FICHA DO CLIENTE</span><h3>Um projecto com nome.</h3><p>Identifique o cliente e registe os detalhes a levar para a proposta e para o contrato.</p><p class="field-description">Dados guardados apenas neste dispositivo e nos ficheiros que exportar. A ligação de partilha contém as escolhas, sem os dados pessoais.</p></div><div class="project-form">${field('clientName','Nome do cliente',project.clientName)}${field('projectName','Nome ou número do projecto',project.projectName)}${field('projectDate','Data da ficha',project.projectDate)}${field('location','Local de instalação',project.location)}${field('contact','Contacto do cliente (opcional)',project.contact)}<h3>Composição de série acordada</h3><p class="field-description">As referências standard confirmadas já acompanham a ficha. Use os campos para acrescentar a composição acordada especificamente com este cliente.</p><p class="field-description">${esc(standardDescription('kitchen'))}</p>${field('kitchenStandard','Cozinha standard: equipamentos e referência',project.kitchenStandard,true)}<p class="field-description">${esc(standardDescription('bathroom'))}</p>${field('bathroomStandard','Banho standard: equipamentos e referência',project.bathroomStandard,true)}<h3>Adaptações deste projecto</h3>${field('adaptations','Alterações de layout, portas, janelas e medidas solicitadas',project.adaptations,true)}${field('notes','Observações para a proposta e contrato',project.notes,true)}<button class="outline" data-go="plans">Rever planta e distribuição ↗</button><button class="outline" data-customize="options">Rever adicionais e custos ↗</button><button class="primary" data-summary>Preparar ficha para impressão ↗</button></div>${costSummaryMarkup(state)}`;
}
export function costSummaryMarkup(state){
 const e=catalogueEstimate(state),adaptations=adaptationEstimate(state);
 return `<section class="project-costs"><h3>Adicionais e valores</h3>${e.lines.length?`<div class="project-cost-list">${e.lines.map(line=>`<article><div><strong>${esc(line.item.label)}</strong><small>${line.quantity} × ${money(line.unitCents)} · PVP actual · ficha p. ${line.item.page}</small>${line.variant?`<small>Tipo: ${esc(line.item.variants.find(v=>v[0]===line.variant)?.[1])}</small>`:''}<small>${line.locations.length?line.locations.map(esc).join(' · '):line.item.model==='opening'&&line.id!=='glass-front'?'Local de aplicação por definir':esc(line.item.scope)}</small></div><b>${money(line.totalCents)}</b></article>`).join('')}</div>`:'<p>Ainda não seleccionou adicionais.</p>'}${adaptations.lines.length?`<h4>Personalizações — acréscimos por definir</h4><div class="project-cost-list adaptation-costs">${adaptations.lines.map(line=>`<article><div><strong>${esc(line.label)}</strong><small>${esc(line.detail)}</small></div><b>Sob orçamento</b></article>`).join('')}</div><p class="field-description">Estas alterações não estão incluídas no subtotal e não são gratuitas. O acréscimo de cada uma será indicado na proposta.</p>`:''}<div class="option-subtotal"><span>Subtotal indicativo com preço publicado</span><strong>${money(e.knownSubtotalCents)}</strong><small>Inclui IVA de 23%. Não é somado IVA novamente.</small></div><dl class="project-pending"><div><dt>Preço base da casa</dt><dd>Por confirmar</dd></div>${e.pending.map(l=>`<div><dt>${esc(l.item.label)}</dt><dd>Sob consulta</dd></div>`).join('')}<div><dt>Transporte e instalação</dt><dd>Por confirmar</dd></div><div><dt>Total da proposta</dt><dd>Por confirmar</dd></div></dl><p class="field-description">PVP actualizado em ${CATALOGUE_EDITION}. O PDF original conserva os preços da edição de julho. O subtotal soma os PVP actuais multiplicados pelas quantidades pedidas; o âmbito de facturação dos artigos sem unidade expressa e os equipamentos já incluídos têm de ser confirmados pela Green Village.</p>${e.unassigned.length?`<p class="project-attention">Falta definir a aplicação de ${e.unassigned.map(l=>esc(l.item.label)).join(', ')}.</p>`:''}</section>`;
}
export function clientSummaryMarkup(project,state){
 return `<section class="client-summary"><span class="eyebrow">PROJECTO DO CLIENTE</span><h3>${esc(project.clientName||'Nome do cliente por preencher')}</h3><dl class="details-list">${[['Projecto',project.projectName],['Data',project.projectDate],['Local',project.location],['Contacto',project.contact],['Cozinha standard confirmada',standardDescription('kitchen')],['Banho standard confirmado',standardDescription('bathroom')],['Acordo específico de cozinha',project.kitchenStandard||'Sem indicações adicionais'],['Acordo específico de banho',project.bathroomStandard||'Sem indicações adicionais'],['Adaptações solicitadas',project.adaptations],['Observações',project.notes]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Por confirmar')}</dd></div>`).join('')}</dl><button class="text-link" data-edit-client>Editar dados do cliente ↗</button></section>${costSummaryMarkup(state)}`;
}
